COMMAND.ACTION:
if test "${aff_method}" = "auto"; then
    ${RT_SBIN}/set_irq_affinity.sh -x local ${iface}
elif test "${aff_method}" = "core"; then
    ${RT_SBIN}/set_irq_affinity.sh -x ${core} ${iface}
fi

if test "${aff_method}" = "auto"; then
    ${RT_SBIN}/set_irq_affinity.sh local ${iface}
elif test "${aff_method}" = "core"; then
    ${RT_SBIN}/set_irq_affinity.sh ${core} ${iface}
fi
